head.script:
// === [Case 1] displayFormatter 결과: 2,002.5 (콤마 + 소수점 6자리 절단) ===
scwin.fmt_case1 = function (data) {
	return WebSquare.text.formatCurrency(data, "#,###.######");
};

// === [Case 2] displayFormatter 결과: "1234567.05" 고정 문자열 ===
scwin.fmt_case2 = function (data) {
	return "1234567.05";
};

scwin.onpageload = function () {
	var tmpJSON = [
		{ "colA": "2002.5",    "colB": "2002.5",    "colC": "2002.5",    "colD": "2002.5" },
		{ "colA": "2002.5",    "colB": "2002.5",    "colC": "2002.5",    "colD": "2002.5" }
	];
	dataList1.setJSON(tmpJSON);
};

// advancedExcelDownload — type 미지정 (기본값 1: displayFormat 적용)
scwin.dl_default_onclick = function (e) {
	gridView1.advancedExcelDownload({ fileName: "case_default.xlsx" });
};

// advancedExcelDownload — type=0 (원본 데이터)
scwin.dl_type0_onclick = function (e) {
	gridView1.advancedExcelDownload({ fileName: "case_type0.xlsx", type: "0" });
};

// advancedExcelDownload — type=1 (displayFormat 적용)
scwin.dl_type1_onclick = function (e) {
	gridView1.advancedExcelDownload({ fileName: "case_type1.xlsx", type: "1" });
};

// advancedExcelDownload — type=2
scwin.dl_type2_onclick = function (e) {
	gridView1.advancedExcelDownload({ fileName: "case_type2.xlsx", type: "2" });
};

// saveCSV — 비교용
scwin.dl_csv_onclick = function (e) {
	gridView1.saveCSV({ fileName: "case_csv.csv" });
};
